const sceneFeedDuration = 380;

const SceneFeed: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Phase timing
  // 0-30: header lands
  // 30-60: type query
  // 60-90: feed cards reveal
  // 90-250: scrolling
  // 250-350: cursor moves to highlighted card, hover effect

  const headerIn = springIn(frame, vfps, 4, "SNAPPY");
  const headerY = interpolate(headerIn, [0, 1], [-140, 0]);

  // Typing progress
  const typed = interpolate(frame, [30, 70], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Side nav fades in with header
  const sideNavIn = springIn(frame, vfps, 12, "GENTLE");

  // Feed cards reveal
  const feedRevealStart = 70;

  // Scroll position
  const scrollPhase1 = interpolate(frame, [100, 200], [0, 800], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scrollPhase2 = interpolate(frame, [220, 290], [0, 600], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const totalScroll = scrollPhase1 + scrollPhase2;

  // Cursor positioning
  // Phase A: cursor moves to search bar (frame 20-40)
  // Phase B: cursor moves to scroll area / drags (frame 80-200)
  // Phase C: cursor moves over highlighted thumbnail (frame 290-340)

  const cursorX = (() => {
    if (frame < 40) {
      return interpolate(frame, [0, 40], [3200, 1900], {
        easing: Easing.out(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    if (frame < 90) {
      return interpolate(frame, [40, 90], [1900, 2400], {
        easing: Easing.inOut(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    if (frame < 220) {
      return interpolate(
        frame,
        [90, 140, 180, 220],
        [2400, 2380, 2410, 2400],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      );
    }
    if (frame < 310) {
      return interpolate(frame, [220, 310], [2400, 1800], {
        easing: Easing.inOut(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    return 1800 + ambientDrift(frame, 8, 60, "cursor-x-hold");
  })();

  const cursorY = (() => {
    if (frame < 40) {
      return interpolate(frame, [0, 40], [2000, 70], {
        easing: Easing.out(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    if (frame < 90) {
      return interpolate(frame, [40, 90], [70, 1200], {
        easing: Easing.inOut(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    if (frame < 220) {
      // scrolling — small jitters
      return 1200 + ambientDrift(frame, 30, 40, "cursor-scroll");
    }
    if (frame < 310) {
      return interpolate(frame, [220, 310], [1200, 950], {
        easing: Easing.inOut(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    return 950 + ambientDrift(frame, 6, 50, "cursor-y-hold");
  })();

  const cursorOpacity = interpolate(frame, [0, 6, 360, 380], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Hover state on highlighted card (Video index 1, "Scaling outbound...")
  const cursorOverHighlight = frame >= 305 && frame <= 360;

  // ============================================================
  // FEED LAYOUT
  // ============================================================
  const FEED_LEFT = 460;
  const FEED_TOP = 200;
  const CARD_WIDTH = 1000;
  const COL_GAP = 60;
  const ROW_GAP = 80;
  const COLS = 3;

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif" }}>
      <Background />

      {/* Side nav */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 140,
          bottom: 0,
          opacity: sideNavIn,
          transform: `translateX(${interpolate(sideNavIn, [0, 1], [-40, 0])}px)`,
        }}
      >
        <SideNav opacity={1} />
      </div>

      {/* Scrolling feed area */}
      <div
        style={{
          position: "absolute",
          left: FEED_LEFT - 40,
          right: 0,
          top: 140,
          bottom: 0,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 40,
            top: FEED_TOP - 140,
            transform: `translateY(${-totalScroll}px)`,
            display: "grid",
            gridTemplateColumns: `repeat(${COLS}, ${CARD_WIDTH}px)`,
            columnGap: COL_GAP,
            rowGap: ROW_GAP,
            paddingBottom: 200,
          }}
        >
          {/* Row 1 — 3 cards (original VIDEOS[0..2]) */}
          {VIDEOS.slice(0, 3).map((v, i) => {
            const cardIn = staggeredSpring(
              frame,
              vfps,
              i,
              feedRevealStart,
              TIMING.staggerItem,
              i === 1 ? "LIQUID" : "GENTLE",
            );
            const driftY = ambientDrift(frame, 1.5, 100 + i * 20, `card-${i}`);
            return (
              <div
                key={i}
                style={{
                  opacity: cardIn,
                  transform: `translateY(${interpolate(cardIn, [0, 1], [40, driftY])}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
                }}
              >
                <VideoCard
                  video={v}
                  width={CARD_WIDTH}
                  emphasize={i === 1 && cursorOverHighlight}
                  cursorOverPlay={i === 1 && cursorOverHighlight && frame > 320}
                />
              </div>
            );
          })}

          {/* Row 2 — 3 more cards */}
          {VIDEOS.slice(3, 6).map((v, i) => {
            const delay = feedRevealStart + 30 + i * TIMING.staggerItem;
            const cardIn = springIn(frame, vfps, delay, "GENTLE");
            const driftY = ambientDrift(frame, 1.5, 110 + i * 20, `card-r2-${i}`);
            return (
              <div
                key={i + 3}
                style={{
                  opacity: cardIn,
                  transform: `translateY(${interpolate(cardIn, [0, 1], [40, driftY])}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
                }}
              >
                <VideoCard video={v} width={CARD_WIDTH} />
              </div>
            );
          })}

          {/* Row 3 — re-use videos to fill scrollable feed */}
          {VIDEOS.slice(0, 3).map((v, i) => {
            const delay = feedRevealStart + 80 + i * TIMING.staggerItem;
            const cardIn = springIn(frame, vfps, delay, "GENTLE");
            const driftY = ambientDrift(frame, 1.5, 120 + i * 20, `card-r3-${i}`);
            const altVideo = {
              ...v,
              title:
                i === 0
                  ? "Lead gen 101: scraping Apollo with Apify Actors"
                  : i === 1
                    ? "Building review-mining pipelines with n8n"
                    : "How I monitor 20+ travel sites for $39/month",
              views:
                i === 0 ? "412K views" : i === 1 ? "189K views" : "73K views",
              age: "1 month ago",
              duration:
                i === 0 ? "11:04" : i === 1 ? "18:22" : "07:51",
            };
            return (
              <div
                key={i + 6}
                style={{
                  opacity: cardIn,
                  transform: `translateY(${interpolate(cardIn, [0, 1], [40, driftY])}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
                }}
              >
                <VideoCard video={altVideo} width={CARD_WIDTH} />
              </div>
            );
          })}

          {/* Row 4 */}
          {VIDEOS.slice(3, 6).map((v, i) => {
            const delay = feedRevealStart + 130 + i * TIMING.staggerItem;
            const cardIn = springIn(frame, vfps, delay, "GENTLE");
            const driftY = ambientDrift(frame, 1.5, 130 + i * 20, `card-r4-${i}`);
            const altVideo = {
              ...v,
              title:
                i === 0
                  ? "Why agents need two pricing layers (essay)"
                  : i === 1
                    ? "OpenClaw agentic night — full talks"
                    : "Scrape + verify emails in one Actor run",
              views:
                i === 0 ? "55K views" : i === 1 ? "121K views" : "94K views",
              age: "2 months ago",
              duration:
                i === 0 ? "14:33" : i === 1 ? "1:24:18" : "09:46",
            };
            return (
              <div
                key={i + 9}
                style={{
                  opacity: cardIn,
                  transform: `translateY(${interpolate(cardIn, [0, 1], [40, driftY])}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
                }}
              >
                <VideoCard video={altVideo} width={CARD_WIDTH} />
              </div>
            );
          })}
        </div>

        {/* Edge fade top/bottom for scroll mask */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            height: 60,
            background: `linear-gradient(to bottom, ${COLORS.bg}, transparent)`,
            pointerEvents: "none",
          }}
        />
      </div>

      {/* Header sits on top */}
      <YTHeader headerY={headerY} query="apify actors tutorial" typed={typed} />

      {/* Cursor */}
      <Cursor x={cursorX} y={cursorY} opacity={cursorOpacity} />

      {/* Click ripple on highlighted card */}
      {frame >= 330 && frame <= 360 && (
        <div
          style={{
            position: "absolute",
            left: cursorX - 60,
            top: cursorY - 60,
            width: 120,
            height: 120,
            borderRadius: "50%",
            border: `3px solid ${COLORS.orange}`,
            opacity: interpolate(frame, [330, 345, 360], [0.6, 0.3, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }),
            transform: `scale(${interpolate(frame, [330, 360], [0.5, 1.6], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            })})`,
            pointerEvents: "none",
          }}
        />
      )}
    </AbsoluteFill>
  );
};

